  res: [{ p: "Haskerdijken", y: 1785, t: "doop van zoon Jelle" }, { p: "Oldelamer", y: 1795, t: "vertrekt naar Peperga en Blesdijke" }, { p: "Peperga", y: 1795, t: "lidmaat, ingekomen van Oldelamer" }, { p: "Oldelamer", y: 1811, t: "woonplaats" }, { p: "Wolvega", y: 1824, t: "verhuist er als weduwe heen" }, { p: "Nijelamer", y: 1826, t: "overlijden" }],
  notes: ["Het gezin woonde in 1785 in Haskerdijken, daarna in Oldelamer, vanaf 1795 in Peperga en Blesdijke en later weer in Oldelamer. Als weduwe trok Geesje in 1824 naar Wolvega; ze overleed in 1826 in Nijelamer, als boerin zonder onroerend goed.",
    { t: "De memorie van 1826 noemt alleen haar zonen Melis en Tymen, niet Elizabeth (kw 79) en Jelle. Waarschijnlijk vat de index de memorie onvolledig samen: de overlijdensakten van Elizabeth (1846) en van Jelle (Echten, december 1826) noemen Geesjen Melis als hun moeder.", k: "afgeleid" }],
